"""Ed25519 v2 tokens: keys generated by the Go `pki tokenkey` tool, verified/minted in Python (cross-language contract)."""
import json, os, subprocess, sys, tempfile, pathlib
import pytest

PKI = pathlib.Path(__file__).resolve().parents[2] / "fep-gateway" / "bin" / "pki"
pytestmark = pytest.mark.skipif(not PKI.exists(), reason="bin/pki not built")


def run(code, env, tmp):
    e = {**os.environ, **env, "PYTHONPATH": str(pathlib.Path(__file__).resolve().parents[1])}
    r = subprocess.run([sys.executable, "-c", code], env=e, capture_output=True, text=True, cwd=tmp)
    return r.returncode, r.stdout.strip(), r.stderr


def test_roundtrip_cap_prefix_and_no_downgrade():
    with tempfile.TemporaryDirectory() as d:
        for cn, mr, sp in (("ems", "viewer", "ems"), ("adm", "admin", "")):
            a = [str(PKI), "tokenkey", "-dir", d, "-cn", cn, "-max-role", mr] + (["-sub-prefix", sp] if sp else [])
            subprocess.run(a, check=True, capture_output=True)
        env = {"GS_TOKEN_TRUST": f"{d}/trust.json", "GS_TOKEN_KEY": f"{d}/adm.tokkey"}
        code = ("from ems import auth,asym_token as a\nimport hmac,hashlib,json\n"
                "t=auth.mint('alice','admin'); print(auth.verify(t)['role'])\n"
                "import base64\n"
                "p=t.split('.')[1]; bad='v2.'+p+'.'+t.split('.')[2][:-2]+'AA'\n"
                "try: auth.verify(bad); print('BAD-ACCEPTED')\nexcept Exception: print('tamper-rejected')\n"
                "h=auth._b64(json.dumps({'sub':'x','role':'admin','jur':['*'],'exp':4102444800}).encode())\n"
                "try: auth.verify(h+'.'+hmac.new(b'dev-secret-do-not-use-in-prod',h.encode(),hashlib.sha256).hexdigest()); print('HMAC-ACCEPTED')\nexcept Exception: print('hmac-rejected')\n")
        rc, out, err = run(code, env, d)
        assert rc == 0, err
        assert out.split() == ["admin", "tamper-rejected", "hmac-rejected"]
        # key capped at viewer: an admin token signed by it is refused; wrong subject prefix refused
        env2 = {"GS_TOKEN_TRUST": f"{d}/trust.json", "GS_TOKEN_KEY": f"{d}/ems.tokkey"}
        code2 = ("from ems import auth\n"
                 "for s,r in (('ems-1','viewer'),('ems-1','admin'),('bob','viewer')):\n"
                 "    try: auth.verify(auth.mint(s,r)); print('ok')\n    except Exception: print('refused')\n")
        rc, out, err = run(code2, env2, d)
        assert rc == 0, err
        assert out.split() == ["ok", "refused", "refused"]
